sketch:
// Thermometer — an NTC on the breadboard.
//
// Push the Temperature slider (or drag the part) while the sketch runs: OUT
// rises across −15…135 °C, hotter reading higher. The readings land nowhere
// without a thermometer equation, but the trend is the point.
const int TEMPERATURE_MIN = -15;
const int TEMPERATURE_MAX = 135;

void setup() {
  Serial.begin(9600);
}

void loop() {
  int raw = analogRead(A0);
  // A map into degrees Celsius — the same ramp the module simulates.
  int dC = map(raw, 0, 1023, TEMPERATURE_MIN, TEMPERATURE_MAX);
  Serial.print("A0 = ");
  Serial.print(raw);
  Serial.print("/1023  ~ ");
  Serial.println(dC / 10.0);
  delay(200);
}
